#!/bin/sh
# offline-run.sh - run one measure.mjs config on a remote host with one CPU taken offline, then restore it.
# usage: offline-run.sh HOST CPU CONFIG OUTDIR [-- extra measure.mjs run args]
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'cpu-measurement-calibration/offline-run.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'offline-run.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
if [ "${1:-}" = "--help" ] || [ "${1:-}" = "-h" ]; then
  cat <<'USAGE'
usage: offline-run.sh HOST CPU CONFIG OUTDIR [-- extra measure.mjs run args]
       offline-run.sh --help | --build | --version

Class (e) driver. On HOST (ssh, BatchMode): records the online state of CPU (it must read 1; cpu0 is refused),
takes CPU offline through run.sh's privileged-container mode, runs
`bun scripts/measure.mjs run --config CONFIG --out OUTDIR --host HOST`, then restores the recorded state on
every exit path (trap on EXIT, INT, TERM, HUP) and reads it back. The final line is
`readback cpuN online=V`; the exit status is nonzero when the readback differs from the recorded state or
the run failed. Expects the image cpucal:1 on HOST and this folder's run.sh at $CAL_REMOTE
(default /var/tmp/cpucal/cpu-measurement-calibration/run.sh).
USAGE
  exit 0
fi
set -eu

HERE=$(cd "$(dirname "$0")" && pwd)
case ${1:-} in
  --build|--version) exec "$HERE/../scripts/cpuprobe.sh" --build ;;
esac
die() { echo "offline-run.sh: $*" >&2; exit 2; }
[ $# -ge 4 ] || die "usage: offline-run.sh HOST CPU CONFIG OUTDIR [-- extra args] (try --help)"
host=$1; cpu=$2; config=$3; out=$4; shift 4
case $cpu in ''|*[!0-9]*) die "CPU must be a whole number" ;; esac
[ "$cpu" != 0 ] || die "refusing to change cpu0"
if [ $# -gt 0 ]; then [ "$1" = "--" ] || die "extra arguments go after --"; shift; fi
REMOTE=${CAL_REMOTE:-/var/tmp/cpucal/cpu-measurement-calibration/run.sh}
rsh() { ssh -o BatchMode=yes "$host" "$@"; }
online="/sys/devices/system/cpu/cpu$cpu/online"

pre=$(rsh "cat $online") || die "cannot read $online on $host"
[ "$pre" = 1 ] || die "cpu$cpu is not online before the run (reads '$pre'); not touching it"
echo "pre-state cpu$cpu online=$pre"

restored=0
rc=0
restore() {
  [ "$restored" = 0 ] || return 0
  restored=1
  echo "restoring cpu$cpu online=$pre" >&2
  rsh "sh $REMOTE cpu-online $cpu $pre" || echo "offline-run.sh: restore command failed" >&2
  post=$(rsh "cat $online" 2>/dev/null) || post=unreadable
  echo "readback cpu$cpu online=$post"
  [ "$post" = "$pre" ] || { echo "offline-run.sh: READBACK MISMATCH (expected $pre)" >&2; rc=1; }
}
finish() { s=$?; [ "$rc" = 0 ] || s=$rc; restore; [ "$rc" = 0 ] || s=$rc; exit "$s"; }
trap finish EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
trap 'exit 129' HUP

rsh "sh $REMOTE cpu-online $cpu 0"
mid=$(rsh "cat $online") || mid=unreadable
echo "offline-state cpu$cpu online=$mid"
[ "$mid" = 0 ] || die "cpu$cpu did not go offline (reads '$mid')"
cd "$HERE/.."
bun scripts/measure.mjs run --config "$config" --out "$out" --host "$host" "$@"
